CREATE TABLE departments(id INT PRIMARY KEY, label VARCHAR);
CREATE TABLE people(id INT PRIMARY KEY, department_id INT, name VARCHAR);
INSERT INTO departments VALUES (10, 'Engineering'), (20, 'Support'), (30, 'Empty');
INSERT INTO people VALUES (1, 10, 'Ada'), (2, 10, 'Grace'), (3, 20, 'Linus'), (4, NULL, 'Unassigned');
SELECT p.id, d.id, p.name, d.label FROM people p JOIN departments d ON p.department_id = d.id ORDER BY p.id;
SELECT a.id, b.id FROM people a JOIN people b ON a.department_id = b.department_id AND a.id <> b.id ORDER BY a.id;
SELECT id FROM people JOIN departments ON FALSE;
SELECT * FROM people a JOIN departments a ON FALSE;
SELECT p.id FROM people p JOIN departments d ON d.missing = p.id;
SELECT people.id FROM people p JOIN departments d ON FALSE;
SELECT p.id, d.label FROM people p LEFT JOIN departments d ON p.department_id = d.id ORDER BY p.id;
SELECT p.name, d.label FROM people p RIGHT JOIN departments d ON p.department_id = d.id ORDER BY d.id, p.id;
SELECT * FROM people RIGHT JOIN departments ON FALSE;
SELECT a.x, b.x FROM (VALUES 1, 2) a(x) CROSS JOIN (VALUES 3, 4) b(x) ORDER BY a.x, b.x;
SELECT a.x, b.x FROM (VALUES 1, 2) a(x), (VALUES 3, 4) b(x) WHERE a.x = 2 ORDER BY b.x;
SELECT COUNT(*) FROM people p CROSS JOIN departments d;
SELECT * FROM (VALUES (1, 10, 'L'), (2, 20, 'M')) a(id, code, l) JOIN (VALUES (1, 10, 'R'), (3, 30, 'S')) b(id, code, r) USING (code, id);
SELECT a.id, b.id, a.code, b.code FROM (VALUES (1, 10)) a(id, code) JOIN (VALUES (1, 10)) b(id, code) USING (id);
SELECT * FROM (VALUES (1, 'a'), (2, 'b')) l(k, v) LEFT JOIN (VALUES (2, 'c'), (3, 'd')) r(k, w) USING (k) ORDER BY k;
SELECT * FROM (VALUES (1, 'a'), (2, 'b')) l(k, v) RIGHT JOIN (VALUES (2, 'c'), (3, 'd')) r(k, w) USING (k) ORDER BY k;
SELECT l.k, r.k, k FROM (VALUES 1) l(k) RIGHT JOIN (VALUES 3) r(k) USING (k);
SELECT l.*, r.* FROM (VALUES (1, 'a')) l(k, v) JOIN (VALUES (1, 'b')) r(k, w) USING (k);
SELECT * FROM (VALUES (1, 'a'), (2, 'c')) l(k, v) NATURAL JOIN (VALUES (1, 'b')) r(k, w);
SELECT * FROM (VALUES 1) l(a) NATURAL JOIN (VALUES 2) r(b);
SELECT * FROM people JOIN departments USING (missing);
SELECT * FROM people JOIN departments USING (id, id);
SELECT d.id, COUNT(p.id) AS people_count FROM departments d LEFT JOIN people p ON d.id = p.department_id GROUP BY d.id ORDER BY d.id;
SELECT p.id, COUNT(*) FROM people p JOIN departments d ON p.department_id = d.id GROUP BY d.id;
SELECT t.a, t.b FROM (VALUES (1, 'a'), (2, 'b')) t(a, b) WHERE t.a > 1;
SELECT a FROM (SELECT id AS a FROM people ORDER BY id FETCH FIRST 2 ROWS ONLY) t ORDER BY a;
SELECT * FROM (TABLE people) t WHERE id = 1;
SELECT p.id FROM (SELECT id FROM people p) t;
SELECT * FROM (VALUES (1, 2)) t(a, a);
SELECT * FROM (VALUES (1, 2)) t(a);
SELECT d.dept_key FROM departments d(dept_key, description) WHERE d.dept_key = 10;
SELECT id FROM departments d(dept_key, description);
SELECT AVG(t.x) FROM (VALUES CAST(1 AS BIGINT), CAST(2 AS BIGINT)) t(x);
SELECT t.x FROM (VALUES (1), (2.5)) t(x) ORDER BY t.x;
SELECT * FROM SYSTEM_RANGE(1, 6, 2);
SELECT * FROM GENERATE_SERIES(6, 1, -2) ORDER BY x DESC;
SELECT COUNT(*) FROM SYSTEM_RANGE(0, 2111222333) r;
SELECT x FROM SYSTEM_RANGE(1, 9223372036854775807) r WHERE x > 1 LIMIT 2 OFFSET 1;
SELECT * FROM SYSTEM_RANGE(1, 2, 0);
CREATE TABLE copied AS SELECT id, name FROM people WHERE department_id = 10;
TABLE copied ORDER BY id;
CREATE TABLE explicit(id INT PRIMARY KEY, name VARCHAR(2)) AS VALUES (5, 'ok');
TABLE explicit;
CREATE TABLE invalid(a INT) AS VALUES (1, 2);
CREATE TABLE duplicate_ids(id INT PRIMARY KEY) AS VALUES 1, 1;
TABLE duplicate_ids;
CREATE TABLE empty_copy AS TABLE people WITH NO DATA;
TABLE empty_copy;
CREATE TABLE target(id INT PRIMARY KEY, name VARCHAR);
INSERT INTO target(name, id) SELECT name, id FROM people WHERE department_id = 10;
INSERT INTO target SELECT id + 10, name FROM target;
SELECT id FROM target ORDER BY id;
INSERT INTO target SELECT id, name FROM people;
SELECT id FROM target ORDER BY id;
INSERT INTO target SELECT id FROM people;
DROP TABLE people, absent;
SELECT COUNT(*) FROM people;
DROP TABLE people, departments;
